export type MetricDefinition = {
  title: string; short: string; formula: string; unit: string; howCalculated: string[];
  sources: MetricSource[]; grain: string; periodRule: string; valueRule: string;
  exclusions: string[]; limitations: string[]; differences: string[]; handbook?: string;
  interpretation?: { normal?: string; warning?: string; critical?: string }; owner?: string;
};
type Profile = Omit<MetricDefinition, "title" | "short" | "formula" | "unit" | "howCalculated" | "interpretation" | "handbook">;
